@startuml

class HospitalHouseMD {
  + name : string
}

class Patient {
  + name : string
  + symptoms : string
}

class Doctor {
  + name : string
  + specialty : string
}

class Diagnosis {
  + description : string
  + date : date
}

class Treatment {
  + name : string
  + description : string
  + currentStage : int
}

class TreatmentStage {
  + stageLevel : int
}

class ConsentForm {
  + signatureDate : date
  + isRetracted : boolean
}

class Illness {
  + name : string
  + priorityScore : PriorityScore
}

enum PriorityScore {
  HIGH
  LOW
}

class TreatmentDatabase {
  + entryCount : int
}

class Nurse {
  + name : string
}

HospitalHouseMD "1" o-- "1..*" Patient
HospitalHouseMD "1" o-- "1..*" Doctor
HospitalHouseMD "1" o-- "1" TreatmentDatabase
