Diagnosis "1" -- "1..*" Treatment
Illness "1" -- "0..*" Diagnosis
Illness "1" -- "0..*" Treatment
Treatment "1" *-- "1" TreatmentStage
Patient "1" -- "0..*" ConsentForm
ConsentForm "1" -- "0..*" Treatment
Doctor "1" -- "0..*" Treatment
Nurse "1" -- "0..*" Treatment

@enduml

